from datetime import date, datetime

from odoo_yaml_test import YamlTransactionCase

from odoo.tests import tagged


@tagged("post_install", "-at_install")
class TestSsiFrequencyRrule(YamlTransactionCase):
    """Assert the dates generated by ``frequency._get_rrule``."""

    def _make_rule(self, code, **values):
        """Create a frequency rule with the given values.

        :param code: unique code of the rule
        :param values: extra field values
        :return: the created ``frequency`` record
        """
        vals = {"name": code, "code": code, "interval": 1}
        vals.update(values)
        return self.env["frequency"].create(vals)

    def _series(self, rule, start, end):
        """Return the series of ``rule`` as ``YYYY-MM-DD`` strings.

        :param rule: a ``frequency`` record
        :param start: start ``datetime`` or ``date``
        :param end: end ``datetime`` or ``date``
        :return: list of date strings
        """
        result = rule._get_rrule(start, end, tz="UTC")
        return [item.strftime("%Y-%m-%d") for item in result]

    def test_second_saturday(self):
        """Assert the second Saturday of each month is generated.

        Pure Python - trigger P1 (L-01: the ``call`` action discards the
        generator returned by ``_get_rrule``).
        """
        rule = self._make_rule(
            "SAT2",
            interval_type="monthly",
            use_byweekday=True,
            sa=True,
            use_setpos=True,
            set_pos=2,
        )
        self.assertEqual(
            self._series(rule, datetime(2026, 1, 1), datetime(2026, 3, 31)),
            ["2026-01-10", "2026-02-14", "2026-03-14"],
        )

    def test_last_saturday(self):
        """Assert the last Saturday of each month is generated.

        Pure Python - trigger P1 (L-01: the ``call`` action discards the
        generator returned by ``_get_rrule``).
        """
        rule = self._make_rule(
            "SATLAST",
            interval_type="monthly",
            use_byweekday=True,
            sa=True,
            use_setpos=True,
            set_pos=-1,
        )
        self.assertEqual(
            self._series(rule, datetime(2026, 1, 1), datetime(2026, 3, 31)),
            ["2026-01-31", "2026-02-28", "2026-03-28"],
        )

    def test_day_31(self):
        """Assert months shorter than 31 days are skipped for day 31.

        Pure Python - trigger P1 (L-01: the ``call`` action discards the
        generator returned by ``_get_rrule``).
        """
        rule = self._make_rule(
            "DAY31",
            interval_type="monthly",
            use_bymonthday=True,
            month_day=31,
        )
        self.assertEqual(
            self._series(rule, datetime(2026, 1, 1), datetime(2026, 6, 30)),
            ["2026-01-31", "2026-03-31", "2026-05-31"],
        )

    def test_leap_day(self):
        """Assert February 29 is generated only in leap years.

        Pure Python - trigger P1 (L-01: the ``call`` action discards the
        generator returned by ``_get_rrule``).
        """
        rule = self._make_rule(
            "LEAP",
            interval_type="yearly",
            use_bymonth=True,
            feb=True,
            use_bymonthday=True,
            month_day=29,
        )
        self.assertEqual(
            self._series(rule, datetime(2024, 1, 1), datetime(2028, 12, 31)),
            ["2024-02-29", "2028-02-29"],
        )

    def test_december(self):
        """Assert the December flag ``des`` maps to month 12.

        Pure Python - trigger P1 (L-01: the ``call`` action discards the
        generator returned by ``_get_rrule``).
        """
        rule = self._make_rule(
            "DEC",
            interval_type="monthly",
            use_bymonth=True,
            des=True,
            use_bymonthday=True,
            month_day=1,
        )
        self.assertEqual(
            self._series(rule, datetime(2026, 1, 1), datetime(2027, 12, 31)),
            ["2026-12-01", "2027-12-01"],
        )

    def test_date_arguments(self):
        """Assert ``date`` arguments work and ``until`` is inclusive.

        Pure Python - trigger P1 (L-01: the ``call`` action discards the
        generator returned by ``_get_rrule``).
        """
        rule = self._make_rule(
            "DATEARG",
            interval_type="weekly",
            use_byweekday=True,
            sa=True,
        )
        self.assertEqual(
            self._series(rule, date(2026, 3, 1), date(2026, 3, 28)),
            ["2026-03-07", "2026-03-14", "2026-03-21", "2026-03-28"],
        )
